#pragma once
namespace forkrot {
inline constexpr char HARDWARE_PAGE[] = R"HWHTML(<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Оборудование · G5500</title><style>body{font:16px system-ui;background:#101721;color:#e5edf5;margin:0;padding:20px}main{max-width:860px;margin:auto}a{color:#6bc9ff}h1{font-size:26px}fieldset{border:1px solid #405267;border-radius:12px;margin:20px 0;padding:18px}label{display:block;margin:14px 0}select,input,button{font:inherit;background:#1b2a3b;color:inherit;border:1px solid #71869c;border-radius:6px;padding:9px;max-width:100%;box-sizing:border-box}select{display:block;width:100%;margin-top:5px}input[type=number]{width:100%}button{cursor:pointer;margin:8px 8px 8px 0}button:disabled{opacity:.45;cursor:default}p{line-height:1.5}.note{padding:14px;border:1px solid #71869c;border-radius:8px}.error{color:#ffb3a5}small{color:#b3c4d5}#message{white-space:pre-wrap}.pin-group{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:0 18px}.pin-group h2{grid-column:1/-1;font-size:19px;margin-bottom:0}.pin-hint{display:block;font-size:13px;margin-top:4px}output{font-weight:600}</style>
<main><a href="/">← Управление</a><h1>Оборудование</h1><p class="note" id="state" role="status">Загрузка состояния…</p>
<p id="effective"></p><p id="failures"></p><p>Изменения применяются после перезагрузки. В течение двух минут откройте эту страницу и подтвердите настройки. До подтверждения движение заблокировано. При неудачном запуске возвращаются подтверждённые параметры; после трёх сбоев включается восстановление.</p>
<form id="hardware"><fieldset><legend>Привод</legend><label>Интерфейс<select name="driveInterface"><option value="0">Штатный блок Yaesu</option><option value="1">Направления и отдельный PWM</option><option value="2">BTS7960 / IBT-2</option></select></label>
<label>Режим<select name="simulation"><option value="0">Физический привод</option><option value="1">Имитация движения</option></select></label>
<label>Выходы BTS7960<select name="pwmInverted"><option value="0">Прямое подключение PWM</option><option value="1">Инвертирующие оптроны RPWM / LPWM</option></select></label><small>Выбирайте по подключённой схеме. ENABLE всегда активен HIGH. CrowPanel без адаптера не управляет физическим приводом.</small></fieldset>
<fieldset><legend>Сеть и Bluetooth</legend><label>Bluetooth<select name="bluetoothEnabled"><option value="0">Выключен</option><option value="1">Включён</option></select></label>
<label>Транспорт<select name="bluetoothMode"><option value="3">Автоматически по плате</option><option value="1">Внешний HC-05</option><option value="2">Встроенный SPP · ESP32</option></select></label>
<label>Точка доступа ESP32<select name="forceApSta"><option value="0">Резервная: при потере сети</option><option value="1">Постоянная: вместе с домашней сетью</option></select></label><small>Постоянная AP и встроенный SPP требуют дополнительной внутренней памяти. На S2/S3 точка доступа сохраняется при подключении к роутеру.</small></fieldset>
<fieldset><legend>Кнопка подтверждения цели</legend><label>GPIO · −1 отключает кнопку<input name="buttonGpio" type="number" min="-1" max="48" step="1" required></label>
<label>Уровень нажатия<select name="buttonActiveLow"><option value="1">LOW · замыкание на GND</option><option value="0">HIGH</option></select></label>
<label>Подтяжка<select name="buttonPullup"><option value="1">Внутренняя к питанию</option><option value="0">Внешняя</option></select></label><small>На CrowPanel кнопка ручки также подтверждает цель; отдельная GPIO-кнопка необязательна. Поведение загрузчика на BOOT не изменяется.</small></fieldset>
<fieldset><legend>Распиновка GPIO</legend><p>В имитации привод и ADC не используют GPIO. Для физического привода задайте все необходимые сигналы. Значение «Не подключён» отключает сигнал. Чтобы отключить EL целиком, освободите все четыре её сигнала.</p><div id="pins"></div><button type="button" id="reset-pins" disabled>Распиновка по умолчанию</button><p id="pin-validation" class="error" role="alert"></p><small id="reserved-pins"></small></fieldset>
<button id="save" disabled>Сохранить и перезапустить</button></form>
<div><button type="button" id="confirm" disabled>Подтвердить и перезапустить</button><button type="button" id="rollback" disabled>Вернуть подтверждённые настройки</button><button type="button" id="recover" disabled>Режим восстановления</button></div>
<p id="message" role="status" aria-live="polite"></p><p><a href="/recovery">Страница восстановления</a> · <a href="/">Основной интерфейс</a></p></main>
<script>'use strict';
let state,metadata,formStamp,dirty=false,busy=false,probe=false,pinError;
const form=document.getElementById('hardware'),msg=document.getElementById('message');
const names=['driveInterface','simulation','bluetoothEnabled','bluetoothMode','forceApSta','buttonGpio','buttonActiveLow','buttonPullup','pwmInverted'];
const labels={azAdc:'Обратная связь AZ · ADC1',elAdc:'Обратная связь EL · ADC1',azNegative:'AZ · отрицательное направление',azPositive:'AZ · положительное направление',elNegative:'EL · отрицательное направление',elPositive:'EL · положительное направление',azSpeedEnable:'AZ · скорость / ENABLE',elSpeedEnable:'EL · скорость / ENABLE',uartRx:'UART0 · RX',uartTx:'UART0 · TX',hc05Rx:'HC-05 · RX контроллера',hc05Tx:'HC-05 · TX контроллера',hc05State:'HC-05 · STATE',rgb:'Адресный RGB',led:'Обычный LED',tftMosi:'SPI · MOSI',tftSck:'SPI · SCK',tftMiso:'SPI · MISO',tftCs:'TFT · CS',tftDc:'TFT · DC',tftRst:'TFT · RESET',touchCs:'Тачскрин · CS',touchIrq:'Тачскрин · IRQ',lcdRs:'LCD · RS',lcdE:'LCD · E',lcdD4:'LCD · D4',lcdD5:'LCD · D5',lcdD6:'LCD · D6',lcdD7:'LCD · D7',buttonGpio:'Кнопка подтверждения цели'};
const groupLabels={drive:'Привод и обратная связь',uart:'UART / HUD',hc05:'Внешний Bluetooth HC-05',indicator:'Индикация',tft:'TFT и тачскрин · общая шина SPI',lcd:'LCD1602'};
const owners={'crowpanel.i2c':'I²C CrowPanel','crowpanel.encoder':'энкодер CrowPanel','crowpanel.backlight':'подсветка CrowPanel','crowpanel.display':'дисплей CrowPanel',flash_psram:'Flash / PSRAM',usb:'USB',unavailable:'недоступен'};
const reasons={unconfirmed:'Предыдущий запуск не подтверждён.',low_memory:'Недостаточно внутренней памяти.',allocation_failed:'Зафиксирован отказ выделения памяти.',radio_failed:'Не удалось запустить радио.',storage_failed:'Не удалось проверить запись настроек.',invalid_config:'Настройки несовместимы с оборудованием.',requested:'Восстановление включено вручную.',initial_setup:'Выберите подключённое оборудование и сохраните настройки.',none:''};
const errors={no_confirmed_configuration:'Подтверждённых настроек пока нет.',invalid_form:'Проверьте все значения.',stale_configuration:'Страница устарела. Обновите страницу.',not_ready:'Ожидаем проверку доступности настроек и запаса памяти.',storage_failed:'Запись не подтверждена. Настройки не применены.',gpio_conflict:'GPIO уже занят.',invalid_gpio:'GPIO недоступен.',invalid_adc_gpio:'Нужен вход ADC1.',input_only_gpio:'Нужен GPIO с выходом.',invalid_pullup:'Внутренняя подтяжка недоступна.',missing_pin:'Укажите обязательный сигнал.',incomplete_uart:'Укажите оба пина UART или отключите оба.',spp_not_supported:'Встроенный SPP доступен только на обычной ESP32.',bluetooth_not_supported:'В этой сборке Bluetooth недоступен.',drive_not_supported:'Интерфейс несовместим с подключённым адаптером.',invalid_hardware:'Проверьте интерфейс и инверсию PWM.'};
const fieldLabel=field=>labels[field.replace(/^pin\./,'')]||field;
const ownerLabel=owner=>owners[owner]||fieldLabel(owner);
function errorText(e){return (e.field?fieldLabel(e.field)+': ':'')+(errors[e.error]||e.error||'Запрос отклонён')+(e.gpio>=0?' GPIO'+e.gpio+'.':'')+(e.owner?' Занят: '+ownerLabel(e.owner)+'.':'');}
async function request(path,body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),5000);try{const r=await fetch(path,{cache:'no-store',signal:controller.signal,...(body?{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(body)}:{})});const j=await r.json();if(!r.ok)throw Error(errorText(j));return j;}finally{clearTimeout(timer);}}
const credentials=()=>({token:state.token,generation:state.generation});
function failureSummary(){document.getElementById('failures').textContent=state&&state.failureCount!==undefined?'Сбои: '+state.failureCount+' / '+state.failureLimit+'. Счётчик сбрасывается после 30 минут нормальной работы.':'';}
const singleAxis=c=>['elAdc','elNegative','elPositive','elSpeedEnable'].every(name=>c.pins[name]<0);
function active(c,d){if(d.group==='drive')return !c.simulation&&!(singleAxis(c)&&['elAdc','elNegative','elPositive','elSpeedEnable'].includes(d.name))&&!(d.name==='elSpeedEnable'&&c.driveInterface===0);if(d.group==='hc05')return !!c.bluetoothEnabled&&(c.bluetoothMode===1||(c.bluetoothMode===3&&!state.classicEsp32));if(d.group==='tft')return metadata.displayKind===1;if(d.group==='lcd')return metadata.displayKind===2;return true;}
function draft(){const c={pins:{...state.configured.pins}};for(const name of names)c[name]=Number(form.elements[name].value);for(const d of metadata.roles){const el=form.elements['pin.'+d.name];if(el)c.pins[d.name]=Number(el.value);}return c;}
const supported=d=>(d.group!=='tft'||metadata.displayKind===1)&&(d.group!=='lcd'||metadata.displayKind===2);
function buildPins(){const container=document.getElementById('pins');container.replaceChildren();for(const [group,title] of Object.entries(groupLabels)){const roles=metadata.roles.filter(d=>d.group===group&&supported(d));if(!roles.length)continue;const section=document.createElement('div');section.className='pin-group';const h=document.createElement('h2');h.textContent=title;section.append(h);for(const d of roles){const label=document.createElement('label'),select=document.createElement('select'),hint=document.createElement('small');label.append(document.createTextNode(labels[d.name]));select.name='pin.'+d.name;select.id='pin-'+d.name;select.setAttribute('aria-describedby',select.id+'-hint');const off=new Option('Не подключён · −1','-1');select.add(off);for(const gpio of metadata.gpios){const bit=d.kind==='adc'?4:d.kind==='output'?2:1;if(gpio.caps&bit)select.add(new Option('GPIO'+gpio.gpio,String(gpio.gpio)));}hint.id=select.id+'-hint';hint.className='pin-hint';label.append(select,hint);section.append(label);}container.append(section);}const reserved=new Map();for(const g of metadata.gpios)if(g.owner&&g.owner!=='unavailable'){if(!reserved.has(g.owner))reserved.set(g.owner,[]);reserved.get(g.owner).push(g.gpio);}document.getElementById('reserved-pins').textContent=reserved.size?'Зарезервированы: '+[...reserved].map(([owner,pins])=>'GPIO '+pins.join(', ')+' · '+ownerLabel(owner)).join('; '):'';}
function checkPins(c){if(metadata.localDriveElectrical&&!c.simulation&&(!singleAxis(c)||c.driveInterface===1))return {error:'drive_not_supported'};if(c.pwmInverted&&c.driveInterface!==2)return {error:'invalid_hardware'};if((c.pins.uartRx<0)!==(c.pins.uartTx<0)||(metadata.hudUart&&c.pins.uartRx<0))return {error:'incomplete_uart'};const used=new Map();for(const d of [...metadata.roles,{name:'buttonGpio',kind:'input',optional:true}]){const button=d.name==='buttonGpio',field=button?d.name:'pin.'+d.name,pin=button?c.buttonGpio:c.pins[d.name];if(!Number.isInteger(pin)||pin< -1||pin>48)return {error:'invalid_gpio',field,gpio:pin};if(pin<0){if((button||active(c,d))&&!d.optional)return {error:'missing_pin',field};continue;}const g=metadata.gpios.find(g=>g.gpio===pin);if(!g||(g.caps&1)===0)return {error:'invalid_gpio',field,gpio:pin,owner:g?.owner};const bit=d.kind==='adc'?4:d.kind==='output'?2:1;if((g.caps&bit)===0)return {error:d.kind==='adc'?'invalid_adc_gpio':'input_only_gpio',field,gpio:pin};if(button&&c.buttonPullup&&(g.caps&8)===0)return {error:'invalid_pullup',field,gpio:pin};if(g.owner)return {error:'gpio_conflict',field,gpio:pin,owner:g.owner};if(!button&&!active(c,d))continue;const owner=used.get(pin);if(owner)return {error:'gpio_conflict',field,gpio:pin,owner};used.set(pin,field);}return null;}
function updatePins(){if(!state||!metadata)return;const c=draft(),used=new Map();for(const d of metadata.roles)if(active(c,d)&&c.pins[d.name]>=0)used.set(c.pins[d.name],'pin.'+d.name);if(c.buttonGpio>=0)used.set(c.buttonGpio,'buttonGpio');for(const d of metadata.roles){const el=form.elements['pin.'+d.name];if(!el)continue;const enabled=active(c,d);for(const option of el.options){const pin=Number(option.value),g=metadata.gpios.find(g=>g.gpio===pin),owner=g?.owner||(used.get(pin)!==el.name?used.get(pin):'');option.disabled=pin>=0&&!!(g?.owner||(enabled&&owner))&&pin!==Number(el.value);option.textContent=pin<0?'Не подключён · −1':'GPIO'+pin+(owner?' · '+ownerLabel(owner):'');}document.getElementById(el.id+'-hint').textContent=Number(el.value)<0?'Не подключён.':enabled?'Сигнал используется.':'Сейчас не используется и не занимает GPIO.';}pinError=checkPins(c);document.getElementById('pin-validation').textContent=pinError?errorText(pinError):'';buttons();}
function buttons(){document.getElementById('save').disabled=busy||!state||!metadata||!!pinError;document.getElementById('reset-pins').disabled=busy||!metadata;document.getElementById('confirm').disabled=busy||!state?.trial||!state.ready||!probe;document.getElementById('rollback').disabled=busy||!state?.hasConfirmed;document.getElementById('recover').disabled=busy||!state||state.recovery;}
form.addEventListener('input',()=>{dirty=true;updatePins();});
async function refresh(){if(busy)return;try{const next=await request('/api/hardware');if(state&&(state.token!==next.token||state.generation!==next.generation))probe=false;state=next;failureSummary();if(!metadata){metadata=await request('/api/hardware/pins');buildPins();}document.getElementById('state').textContent=state.recovery?'Режим восстановления. Привод и Bluetooth отключены. '+(reasons[state.reason]||''):state.trial?'Пробный запуск. До отката: '+Math.ceil(state.remainingMs/1000)+' с.':'Работают подтверждённые настройки.';document.getElementById('effective').textContent='Свободная внутренняя память: '+state.heapFree+' байт; крупнейший блок: '+state.heapMaxBlock+' байт. Bluetooth: '+state.backend+'.';if(!dirty){formStamp=credentials();for(const name of names)form.elements[name].value=state.configured[name];for(const d of metadata.roles){const el=form.elements['pin.'+d.name];if(el)el.value=state.configured.pins[d.name];}}form.elements.bluetoothMode.options[2].disabled=!state.sppSupported;form.elements.forceApSta.disabled=!state.classicEsp32;form.elements.driveInterface.options[1].disabled=state.separateDrive===false;form.elements.driveInterface.options[2].disabled=state.btsDrive===false;form.elements.bluetoothEnabled.disabled=!!state.crowpanelLocalDrive;if(state.crowpanelLocalDrive)form.elements.bluetoothEnabled.value="0";updatePins();if(state.trial&&state.ready&&!probe){await request('/api/hardware/probe',credentials());probe=true;}buttons();}catch(e){msg.textContent='Не удалось получить состояние: '+e.message;probe=false;document.getElementById('confirm').disabled=true;}}
async function apply(path,values){if(busy||!state)return;busy=true;msg.textContent='Сохраняем настройки…';buttons();try{await request(path,{...(path==='/api/hardware'?formStamp:credentials()),...values});msg.textContent='Сохранено. Устройство перезапускается. После подключения откройте эту страницу.';dirty=false;probe=false;setTimeout(()=>{busy=false;refresh();},4000);}catch(e){msg.textContent=e.message;busy=false;buttons();}}
form.addEventListener('submit',e=>{e.preventDefault();updatePins();if(pinError)return;const body={};for(const name of names)body[name]=form.elements[name].value;for(const d of metadata.roles){const el=form.elements['pin.'+d.name];if(el)body['pin.'+d.name]=el.value;}apply('/api/hardware',body);});
document.getElementById('reset-pins').onclick=()=>{for(const d of metadata.roles){const el=form.elements['pin.'+d.name];if(el)el.value=d.default;}form.elements.buttonGpio.value=metadata.buttonDefault;dirty=true;updatePins();};
document.getElementById('confirm').onclick=()=>apply('/api/hardware/confirm',{});document.getElementById('rollback').onclick=()=>apply('/api/hardware/rollback',{});document.getElementById('recover').onclick=()=>apply('/api/hardware/recovery',{});refresh();setInterval(refresh,2000);
</script></html>)HWHTML";
} // namespace forkrot
